using System; using System.Drawing; using System.Drawing.Imaging; using PdfiumViewer; class V { static void Main(string[] a) { using(var before=PdfDocument.Load(a[0])) using(var after=PdfDocument.Load(a[1])) using(var sheet=new Bitmap(600,200*before.PageCount)) { using(var g=Graphics.FromImage(sheet)) { g.Clear(Color.White); for(int i=0;i<before.PageCount;i++) { if(Math.Abs(before.PageSizes[i].Width-after.PageSizes[i].Width)>2 || Math.Abs(before.PageSizes[i].Height-after.PageSizes[i].Height)>2) throw new Exception("Page dimensions"); using(var x=before.Render(i,290,190,72,72,PdfRenderFlags.Annotations)) using(var y=after.Render(i,290,190,72,72,PdfRenderFlags.Annotations)) { g.DrawImage(x,0,i*200,290,190); g.DrawImage(y,300,i*200,290,190); } } } sheet.Save(a[2],ImageFormat.Png); } } }